mapper.select:
select r.receipt_id as receiptId, r.enterprise_id as enterpriseId, r.receipt_no as receiptNo, r.order_id as orderId, r.receipt_type as receiptType, r.total_qty as totalQty, r.receiver_id as receiverId, r.receiver_name as receiverName, r.receipt_time as receiptTime, r.remark as remark, r.create_time as createTime, o.order_no as orderNo from t_receipt r left join t_purchase_order o on o.order_id = r.order_id where r.enterprise_id = #{enterpriseId}
and r.order_id = #{orderId}
order by r.receipt_id desc
